import numpy as np
from scipy.optimize import least_squares
t,x,v,a=df['t'].values,df['x'].values,df['v'].values,df['dv_dt'].values
one=np.ones_like(t)
def model(p):
    w,pw,qw=p[0],p[1],p[2]
    X=np.column_stack([one,x,v,np.abs(x)**pw,np.sign(v)*np.abs(v)**qw,np.cos(w*t),np.sin(w*t)])
    return X
def resid(p):
    X=model(p); c=np.linalg.lstsq(X,a,rcond=None)[0]; return X@c-a
best=None
for w0 in [0.3,0.31]:
  for p0 in [1.5,2,3,4]:
    for q0 in [1,1.5,2]:
        r=least_squares(resid,[w0,p0,q0])
        n=np.mean(r.fun**2)/np.var(a)
        if best is None or n<best[0]: best=(n,r.x)
print(best)
